define(["jquery"],function($){let apiPromise;const loadApi=url=>{if(window.Vimeo&&window.Vimeo.Player){return Promise.resolve(window.Vimeo)}if(!apiPromise){apiPromise=new Promise((resolve,reject)=>{const script=document.createElement("script");script.src=url;script.onload=()=>resolve(window.Vimeo);script.onerror=reject;document.head.appendChild(script)})}return apiPromise};class VimeoAdapter{constructor(root,config){this.root=root;this.config=config;this.handlers={};this.current=0;this.duration=0;this.rate=1}initialise(){return loadApi(this.config.vimeoplayerurl).then(Vimeo=>{const options={id:Number(this.config.vimeoid),responsive:true};if(this.config.vimeohash){options.h=this.config.vimeohash}this.player=new Vimeo.Player("videoprogress-vimeo-player",options);this.player.on("play",()=>this.emit("play"));this.player.on("pause",()=>this.emit("pause"));this.player.on("ended",()=>this.emit("ended"));this.player.on("timeupdate",data=>{this.current=data.seconds;this.duration=data.duration;this.emit("timeupdate",data.seconds)});this.player.on("seeked",data=>{this.current=data.seconds;this.emit("seek",data.seconds)});this.player.on("playbackratechange",data=>{this.rate=data.playbackRate;const maximum=Number(this.config.maxplaybackrate||0);if(maximum>0&&this.rate>maximum){this.player.setPlaybackRate(maximum).catch(()=>{});this.rate=maximum}this.emit("ratechange",this.rate)});return Promise.all([this.player.ready(),this.player.getDuration()]).then(values=>{this.duration=values[1];return this})})}play(){return this.player.play()}pause(){return this.player.pause()}getCurrentTime(){return Number(this.current||0)}getDuration(){return Number(this.duration||0)}getPlaybackRate(){return Number(this.rate||1)}seek(position){return this.player.setCurrentTime(Math.max(0,Number(position)))}onPlay(handler){this.on("play",handler)}onPause(handler){this.on("pause",handler)}onTimeUpdate(handler){this.on("timeupdate",handler)}onSeek(handler){this.on("seek",handler)}onEnded(handler){this.on("ended",handler)}onRateChange(handler){this.on("ratechange",handler)}on(name,handler){this.handlers[name]=(this.handlers[name]||[]).concat(handler)}emit(name,...args){(this.handlers[name]||[]).forEach(handler=>handler(...args))}}const create=(root,config)=>new VimeoAdapter(root,config).initialise();return{create:create}});